import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import ProgressLoading from "../../../components/progress_loading";
import {
  Card,
  Row,
  Col,
  Label,
  Input,
  Button,
  CardHeader,
  CardTitle,
  CardBody,
  CardFooter,
} from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import CustomDatePicker from "../../../components/datepicker";
import useRoaming from "../../../hooks/use_roaming";
import { BalanceFormatter } from "../../../helper/balance_formatter";

const AllRoaming = () => {
  const {
    getOperators,
    searchRoaming,
    operatorsList,
    searchResult,
    formData,
    setFormData,
    loadings,
  } = useRoaming();

  useEffect(() => {
    getOperators();
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="Roaming"
        data={[{ title: "Roaming" }, { title: "Roaming" }]}
      />
      {/* searchbar */}
      <Card>
        <CardHeader>
          <CardTitle>Search</CardTitle>
        </CardHeader>
        <CardBody>
          <Row>
            {/* operator */}
            <Col xs="12" sm="6" md="4" className={"mb-1"}>
              <Label for="operator">Operator</Label>
              <Select
                isClearable={false}
                theme={selectThemeColors}
                closeMenuOnSelect={true}
                placeholder="select option"
                maxMenuHeight={120}
                options={operatorsList}
                className={`react-select`}
                classNamePrefix="select"
                id="operator"
                name="operator"
                isDisabled={loadings.getOperators}
                value={formData.operator}
                onChange={(value) =>
                  setFormData({ ...formData, operator: value })
                }
              />
            </Col>
            {/* start */}
            <Col xs="12" sm="6" md="4" className={"mb-1"}>
              <Label for="start">Start Time</Label>
              <CustomDatePicker
                value={formData.start}
                onChange={(value) => setFormData({ ...formData, start: value })}
                inputPlaceholder="select date"
                calendarPopperPosition={"bottom"}
              />
            </Col>
            {/* end */}
            <Col xs="12" sm="6" md="4" className={"mb-1"}>
              <Label for="end">End Time</Label>
              <CustomDatePicker
                value={formData.end}
                onChange={(value) => setFormData({ ...formData, end: value })}
                inputPlaceholder="select date"
                calendarPopperPosition={"bottom"}
              />
            </Col>
          </Row>
        </CardBody>
        <CardFooter>
          <Col xs="12" className={"d-flex justify-content-end"}>
            <Button
              onClick={searchRoaming}
              disabled={loadings.searchRoaming}
              style={{ width: 150, marginLeft: 24 }}
              color="primary"
            >
              {loadings.searchRoaming ? "Searching..." : "Search"}
            </Button>
          </Col>
        </CardFooter>
      </Card>
      <Row>
        {searchResult
          ? Object.keys(searchResult).map((item, index) => (
              <Col key={index} xs="12" sm="6" md="4" className={"mb-1"}>
                <Card>
                  <CardBody
                    className={
                      "d-flex align-items-center justify-content-between"
                    }
                  >
                    <CardTitle className={"mb-0"}>{item}</CardTitle>
                    <CardTitle className={"mb-0"}>
                      {BalanceFormatter({
                        type: item,
                        value: searchResult[item],
                      })}
                    </CardTitle>
                  </CardBody>
                </Card>
              </Col>
            ))
          : null}
      </Row>
    </Fragment>
  );
};
export default AllRoaming;
