import { useState } from "react";
import useHttp from "./use_http";
import toast from "react-hot-toast";

const useRoaming = () => {
  const { httpService } = useHttp();
  const [loadings, setLoadings] = useState({
    getOperators: false,
    searchRoaming: false,
  });

  const [formData, setFormData] = useState({
    operator: null,
    start: null,
    end: null,
  });
  const [operatorsList, setOperatorsList] = useState([]);
  const [searchResult, setSearchResult] = useState(null);

  const getOperators = async () => {
    let array = [];
    try {
      setLoadings({ ...loadings, getOperators: true });
      const response = await httpService.get("/v1/roaming/operators");
      setLoadings({ ...loadings, getOperators: false });
      if (response.data.data) {
        Object.keys(response.data.data).map((item) => {
          array.push({ label: item, value: response.data.data[item] });
        });
        setOperatorsList(array);
      }
    } catch ({ err, response }) {
      setLoadings({ ...loadings, getOperators: false });
    }
  };

  const searchRoaming = async () => {
    if (!formData.operator) {
      toast.error("Please select an operator.");
    } else if (!formData.start) {
      toast.error("Please select start time.");
    } else if (!formData.end) {
      toast.error("Please select end time.");
    } else {
      let startConvertedDate = `${formData.start.year}-${
        formData.start.month < 10
          ? "0" + formData.start.month
          : formData.start.month
      }-${
        formData.start.day < 10 ? "0" + formData.start.day : formData.start.day
      }`;

      let endConvertedDate = `${formData.end.year}-${
        formData.end.month < 10 ? "0" + formData.end.month : formData.end.month
      }-${formData.end.day < 10 ? "0" + formData.end.day : formData.end.day}`;

      let postData = {
        source_mccmnc: formData.operator.value,
        start_time: `${startConvertedDate}T00:00:00Z`,
        end_time: `${endConvertedDate}T00:00:00Z`,
      };
      try {
        setLoadings({ ...loadings, searchRoaming: true });
        const response = await httpService.post(
          "/v1/cdrs/roaming_usage",
          postData
        );
        setLoadings({ ...loadings, searchRoaming: false });
        if (response.data.data) {
          setSearchResult(response.data.data);
        }
      } catch ({ err, response }) {
        setLoadings({ ...loadings, searchRoaming: false });
      }
    }
  };

  const exports = {
    getOperators,
    searchRoaming,
    operatorsList,
    searchResult,
    formData,
    setFormData,
    loadings,
  };
  return exports;
};
export default useRoaming;
